package com.aistock.prediction.comparisonai;
import com.fasterxml.jackson.databind.node.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.prediction.comparisonai.ComparisonAiSamples.*;
@org.junit.jupiter.api.extension.ExtendWith(org.springframework.boot.test.system.OutputCaptureExtension.class)
class ComparisonAiTemplateTest {
 static ObjectNode valid(ComparisonAiFacts.Facts f){var root=M.createObjectNode();var ps=root.putArray("paragraphs");for(String kind:new String[]{"overview","readout","risk"}){var required=ComparisonAiTemplate.required(kind,f.values());var p=ps.addObject().put("kind",kind).put("template",required.stream().sorted().map(k->"{{"+k+"}}").collect(java.util.stream.Collectors.joining("。")));p.set("refs",M.valueToTree(required.stream().sorted().toList()));}return root;}
 @Test void rendersExactFixedFacts(){var f=ComparisonAiFacts.build(saved(),"model",M);var rendered=ComparisonAiTemplate.render(valid(f),f,M);assertEquals(3,rendered.size());assertTrue(rendered.get(0).path("text").asText().contains("-1.000000"));}
 @Test void rejectsUnsupportedNumbersRelationsAndNegation(){var f=ComparisonAiFacts.build(saved(),"model",M);for(String literal:new String[]{"收益12%","这只更强","并非","未来肯定上涨","<b>"}){var raw=valid(f);var p=(ObjectNode)raw.path("paragraphs").get(0);p.put("template",literal+p.path("template").asText());assertThrows(RuntimeException.class,()->ComparisonAiTemplate.render(raw,f,M),literal);}}
 @Test void rejectsMissingContextReferenceAndWrongParagraph(){var f=ComparisonAiFacts.build(saved(),"model",M);var raw=valid(f);var p=(ObjectNode)raw.path("paragraphs").get(2);p.put("template","{{HISTORY_LIMIT}}");p.set("refs",M.valueToTree(java.util.List.of("HISTORY_LIMIT")));assertThrows(RuntimeException.class,()->ComparisonAiTemplate.render(raw,f,M));var invalid=valid(f);((ObjectNode)invalid.path("paragraphs").get(0)).put("kind","unknown");assertThrows(RuntimeException.class,()->ComparisonAiTemplate.render(invalid,f,M));}

 @Test void rejectsStandaloneAssertionsEvenWithAllValidReferences(){var f=ComparisonAiFacts.build(saved(),"model",M);for(String sentence:new String[]{"实际采用前复权口径。","前者大于后者。","未来有增长空间。"}){var raw=valid(f);var part=(ObjectNode)raw.path("paragraphs").get(0);part.put("template",sentence+part.path("template").asText());assertThrows(RuntimeException.class,()->ComparisonAiTemplate.render(raw,f,M),sentence);}}
 @Test void rejectedStandaloneTextLogsOnlyBoundedReason(org.springframework.boot.test.system.CapturedOutput output){var f=ComparisonAiFacts.build(saved(),"model",M);var raw=valid(f);var part=(ObjectNode)raw.path("paragraphs").get(0);part.put("template","机密诊断样例。"+part.path("template").asText());assertThrows(RuntimeException.class,()->ComparisonAiTemplate.render(raw,f,M));assertTrue(output.getAll().contains("rule=UNSUPPORTED_CLAUSE"));assertFalse(output.getAll().contains("机密诊断样例"));}
}
